namespace BCSStudyHub.Application.Library;

/// <summary>
/// Provider-neutral binary storage. Keys are generated by the provider and never derived from user input,
/// so a local filesystem adapter can be swapped for object storage without changing the library module.
/// </summary>
public interface IFileStorage
{
    string ProviderName { get; }

    /// <summary>Creates a new collision-resistant key.</summary>
    string CreateKey();

    /// <summary>Writes the stream under a new key. Fails if the key already exists.</summary>
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Opens a stored object for streaming, or returns null when it does not exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    /// <summary>Deletes an object. Deleting a missing key is not an error.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
